def valid_parentheses(s):
    stack = []
    pairs = {')': '(', ']': '[', '}': '{'}
    for ch in s:
        if ch == '(' or ch == '[' or ch == '{':
            stack.append(ch)
        else:
            if not stack or stack[-1] != pairs[ch]:
                return False
            stack.pop()
    return not stack

def single_number(nums):
    res = 0
    for x in nums:
        res = res ^ x
    return res

def has_cycle(nums, pos):
    if not nums:
        return False
    n = len(nums)
    def nxt(i):
        if i == n - 1:
            return pos if pos >= 0 else -1
        return i + 1
    slow = 0
    fast = 0
    while fast != -1 and nxt(fast) != -1:
        slow = nxt(slow)
        fast = nxt(nxt(fast))
        if slow == fast:
            return True
    return False

def length_of_longest_substring(s):
    seen = {}
    left = 0
    best = 0
    for right in range(len(s)):
        ch = s[right]
        if ch in seen and seen[ch] >= left:
            left = seen[ch] + 1
        seen[ch] = right
        cur = right - left + 1
        if cur > best:
            best = cur
    return best

def search_in_rotated_sorted_array(nums, target):
    lo = 0
    hi = len(nums) - 1
    while lo <= hi:
        mid = (lo + hi) // 2
        if nums[mid] == target:
            return mid
        if nums[lo] <= nums[mid]:
            if nums[lo] <= target < nums[mid]:
                hi = mid - 1
            else:
                lo = mid + 1
        else:
            if nums[mid] < target <= nums[hi]:
                lo = mid + 1
            else:
                hi = mid - 1
    return -1

def coin_change(coins, amount):
    INF = amount + 1
    dp = [INF] * (amount + 1)
    dp[0] = 0
    for i in range(1, amount + 1):
        for c in coins:
            if c <= i and dp[i - c] + 1 < dp[i]:
                dp[i] = dp[i - c] + 1
    if dp[amount] == INF:
        return -1
    return dp[amount]

def jump_game(nums):
    reach = 0
    for i in range(len(nums)):
        if i > reach:
            return False
        if i + nums[i] > reach:
            reach = i + nums[i]
    return True

def longest_valid_parentheses(s):
    stack = [-1]
    best = 0
    for i in range(len(s)):
        ch = s[i]
        if ch == '(':
            stack.append(i)
        else:
            stack.pop()
            if stack:
                cur = i - stack[-1]
                if cur > best:
                    best = cur
            else:
                stack.append(i)
    return best

def sliding_window_maximum(nums, k):
    if not nums or k <= 0:
        return []
    dq = []
    res = []
    for i in range(len(nums)):
        x = nums[i]
        while dq and nums[dq[-1]] <= x:
            dq.pop()
        dq.append(i)
        if dq[0] <= i - k:
            dq.pop(0)
        if i >= k - 1:
            res.append(nums[dq[0]])
    return res
